	// 計算所有隊伍費用總額
	calcTotalTeamsCost(teams) {
		return teams.reduce((total, item) => {
			const numericPrice = item.priceNum;
			// const numericPrice = Number(item.price.replace('$', '').replace(',', '')); // 處理有逗號的價格也安全
			return total + (isNaN(numericPrice) ? 0 : numericPrice); // 保險起見，排除非數字
		}, 0);
	}

	generateUUIDv4() {
		return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
			const r = Math.random() * 16 | 0;
			const v = c === 'x' ? r : (r & 0x3 | 0x8);
			return v.toString(16);
		});
	}

	// 按下確定訂單
	async confirmOrderDetail() {
		this.layoutService.setPageLoading(true);
		this.buyerForm.controls.submitTaiwanTime.setValue(moment(new Date()).format('YYYY-MM-DD HH:mm:ss'));
		this.buyerForm.controls.isLock.setValue(true);
		this.buyerForm.controls.groupIdForSentEmail.setValue(this.generateUUIDv4());
		let selectedTeamsIdArr = [];
		const selectedTeamsList = this.teamsList.filter((item) => {
			// 將被選取的隊伍整理成id陣列，送去checkThisTeamIsLock做檢查
			if (!!item.isSelected) selectedTeamsIdArr.push(item.id)
			return !!item.isSelected
		});
		// console.log(selectedTeamsList);
		let checkAnyTeamsIsLock = await this.checkAnyTeamsIsLock(selectedTeamsIdArr);
		console.log(checkAnyTeamsIsLock);
		if (!!checkAnyTeamsIsLock) {
			this.messageService.add({
				severity: 'error',
				summary: `注意`,
				detail: '您選中的隊伍已被別人搶先一步，請重新刷新選取',
				icon: 'bounce animated',
				life: 5000,
			});
			this.layoutService.setPageLoading(false);
			return;
		} else {
			await this.updateTeamInfo(selectedTeamsIdArr);
		}
		console.log(this.buyerForm.value);
	}

	// - 確認是否有任一隊伍是否已被其他人選取
	async checkAnyTeamsIsLock(selectedTeamsIdArr: string[]): Promise<boolean> {
		let flag = 0;
		try {
			const { data, error } = await this.supabaseService.getTeamsById(selectedTeamsIdArr);

			if (!!data) {
				console.log(data);
				data.filter((item) => {
					if (!!item.isLock) flag++
				})
				if (flag > 0) return true;
				else return false;
			}

			// 檢查是否有任何一個 team 是 lock 的
			// const isAnyLocked = data.some(item => !!item.isLock);
			// return isAnyLocked;
		} catch (err) {
			console.error('Unexpected error:', err);
			return false;
		}
	}

	// - 送出表單
	async updateTeamInfo(selectedTeamsIdArr: string[]): Promise<boolean> {
		try {
			const { data, error } = await this.supabaseService.updateTeamInfo(selectedTeamsIdArr, this.buyerForm.value);

			if (!!data) {
				this.messageService.add({
					severity: 'success',
					summary: `成功`,
					detail: '表單送出成功',
					icon: 'bounce animated',
					life: 5000,
				});
				this.mode = 'success';
				this.layoutService.setPageLoading(false);
				setTimeout(() => {
					window.location.reload();
				}, 10000)
			}
		} catch (err) {
			console.error('Unexpected error:', err);
			return false;
		}
	}
