import { Component, OnInit, PLATFORM_ID, ViewChild, ChangeDetectorRef, Inject } from '@angular/core';
import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { ActivatedRoute, Router } from '@angular/router';
import { Title } from '@angular/platform-browser';

// ** rxjs
import { finalize, switchMap, tap } from 'rxjs/operators';
import { of, Observable } from 'rxjs';

// ** service
import { LayoutService } from '@app/core/services/layout.service';
import { ProductsService } from '@app/core/services/products.service';
import { SuccessService } from '@app/core/services/success.service';

//  ** env

// ** primeng
import { Paginator } from 'primeng/paginator';

@Component({
	selector: 'app-solution-explore',
	templateUrl: './solution-explore.component.html',
	styleUrls: ['./solution-explore.component.scss'],
})
export class SolutionExploreComponent implements OnInit {
	@ViewChild(Paginator) paginator: Paginator;
	@ViewChild('searchBtn') searchBtn;

	isBrowser: boolean;

	typeMap = {
		gov: '國軍單位',
		police: '警察機關',
		judicial: '檢調司法',
		business: '工業商業',
		edu: '教育',
		transport: '運輸物流',
		medical: '能源醫療',
		'info-security': '資安',
		'national-security':'國安',
		'public-security': '治安'
	};

	// ** 搜尋欄位的值
	keywordRaw = '';
	// ** 推薦關鍵字 tag
	recommendTags = [
		'國軍單位',
		'警察機關',
		'檢調司法',
		'運輸物流',
		'人工智慧',
		'大數據',
		'資訊安全',
		'物聯網',
		'科技偵查',
		'數據整合',
		'海巡署',
		'調查局',
		'國安',
		'資安',
		'治安'
	];

	// ** 所有的 成功案咧 清單 (全部)
	successSheet = [];
	// ** 所有的 成功案咧 清單 (by 關鍵字搜尋)
	successByKeyword = [];
	// ** 當前應呈現的 成功案咧 資料
	successByPage = [];

	constructor(
		@Inject(DOCUMENT) private document: Document,
		@Inject(PLATFORM_ID) private platformId,
		private route: ActivatedRoute,
		private title: Title,
		private router: Router,
		private productsService: ProductsService,
		private successService: SuccessService,
		private layoutService: LayoutService,
		private cdr: ChangeDetectorRef
	) {
		this.isBrowser = isPlatformBrowser(this.platformId);
	}

	ngOnInit(): void {
		this.initPage();
	}

	initPage() {
		this.route.params
			.pipe(
				tap(() => this.layoutService.setPageLoading(true)),
				tap((params) => {
					const canonical = this.document.querySelector('link[rel="canonical"]') as HTMLAnchorElement | null;
					if (canonical) canonical.href = `https://www.kunyoutech.com.tw/solutions/explore`;
				}),
				tap((params) => console.log(params['keyword'] && '')),
				tap((params) => (this.keywordRaw = params['keyword'] ? this.typeMap[params['keyword']] : '')),
				tap(() => this.getSuccessSheet()),
				finalize(() => this.layoutService.setPageLoading(false))
			)
			.subscribe();
	}

	// - 取得所有資料 (進到頁面只呼叫一次)
	getSuccessSheet() {
		of(this.layoutService.setPageLoading(true))
			.pipe(
				switchMap(() => this.getSuccessSheet$()),
				tap((res) => (this.successSheet = [...res])),
				tap((res) => (this.successByKeyword = [...res])),
				tap(() => (this.keywordRaw ? this.searchBtn.nativeElement.click() : this.getDataByPage({ page: 0 }))),
				finalize(() => this.layoutService.setPageLoading(false))
			)
			.subscribe();
	}

	// - 按下搜尋
	getSuccessByKeyword(rawString, e) {
		of(this.layoutService.setPageLoading(true))
			.pipe(
				tap(() => {
					const keywords = rawString?.split(' ');
					if (!keywords.length) return (this.successByKeyword = [...this.successSheet]);
					this.resetSuccessData(e);
					this.successSheet.forEach((success) => {
						const isRelated = success.MetaTags?.some((x) =>
							keywords.some(
								(y) =>
									new RegExp(y, 'i').test(x) ||
									new RegExp(x, 'i').test(y) ||
									new RegExp(success.Name, 'i').test(y) ||
									new RegExp(y, 'i').test(success.Name)
							)
						);
						this.successByKeyword = isRelated
							? [...this.successByKeyword, success]
							: [...this.successByKeyword];
					});
				}),
				tap(() => this.getDataByPage({ page: 0 })),
				finalize(() => this.layoutService.setPageLoading(false))
			)
			.subscribe();
	}

	// - 分頁
	getDataByPage(event) {
		of(this.layoutService.setPageLoading(true))
			.pipe(
				tap(() => (this.successByPage = this.successByKeyword.slice(event.page * 6, (event.page + 1) * 6))),
				tap(() => {
					if (!this.isBrowser) return;
					let element = document.getElementById('exploreArea');
					let targetPosition = element.offsetTop - 65;
					setTimeout(() => window.scrollTo({ top: targetPosition, behavior: 'smooth' }), 300);
				}),
				finalize(() => this.layoutService.setPageLoading(false))
			)
			.subscribe();
	}

	// - 前往成功案例內頁
	goToSuccess(NameEN) {
		of(this.layoutService.setPageLoading(true))
			.pipe(tap(() => setTimeout(() => this.router.navigateByUrl(`success/${NameEN}`))))
			.subscribe();
	}

	// - reset 成功案例搜尋資料 to default
	resetSuccessData(e) {
		this.successByKeyword = [];
		this.successByPage = [];
		this.paginator?.changePageToFirst(e);
	}

	// ? API

	getSuccessSheet$(): Observable<any> {
		return this.successService.getSuccessSheet().pipe();
	}
}
